async def run(page, results):
    # GitHub issue titles typically have this data attribute
    issue_links = page.locator('a[data-hovercard-type="issue"]')
    titles = []

    # Wait for at least one element to be present
    try:
        await issue_links.first.wait_for(state='visible', timeout=5000)
    except:
        pass

    count = await issue_links.count()
    limit = min(count, 10)

    for i in range(limit):
        text = await issue_links.nth(i).text_content()
        if text:
            titles.append(text.strip())

    return {"issue_titles": titles}
